31	/// Checks if any of the enabled rules is in the project domain and requires the module graph.
32	struct NeedsModuleGraph<'a> {
33	    enabled_rules: Option<&'a [RuleFilter<'a>]>,
34	    needs_module_graph: bool,
35	}
36	
37	impl<'a> NeedsModuleGraph<'a> {
38	    fn new(enabled_rules: Option<&'a [RuleFilter<'a>]>) -> Self {
39	        Self {
40	            enabled_rules,
41	            needs_module_graph: false,
42	        }
43	    }
44	
45	    fn compute(mut self) -> bool {
46	        biome_js_analyze::visit_registry(&mut self);
47	        self.needs_module_graph
48	    }
49	}
