51	impl RegistryVisitor<JsLanguage> for NeedsModuleGraph<'_> {
52	    fn record_rule<R>(&mut self)
53	    where
54	        R: Rule<Options: Default, Query: Queryable<Language = JsLanguage, Output: Clone>> + 'static,
55	    {
56	        let filter = RuleFilter::Rule(<R::Group as RuleGroup>::NAME, R::METADATA.name);
57	
58	        if self
59	            .enabled_rules
60	            .is_some_and(|enabled_rules| enabled_rules.contains(&filter))
61	            && (R::METADATA.domains.contains(&RuleDomain::Project)
62	                || R::METADATA.domains.contains(&RuleDomain::Types))
63	        {
64	            self.needs_module_graph = true;
65	        }
66	    }
67	}
